class Solution:
    def findDuplicate(self, nums: List[int]) -> int:
        slow = fast = 0
        while True:                         # 把 i -> nums[i] 看成链表
            slow = nums[slow]
            fast = nums[nums[fast]]
            if slow == fast:
                break
        slow = 0                            # 一个回到起点，再同速走
        while slow != fast:
            slow = nums[slow]
            fast = nums[fast]
        return slow                         # 相遇点就是环的入口

from bisect import bisect_left

class Solution:
    def findDuplicate(self, nums: List[int]) -> int:
        return bisect_left(range(len(nums)), True, key=lambda x: sum(v <= x for v in nums) > x)

